204	// ---------------------------------------------------------------------------
205	// Visit-scoped message state, keyed by account+conversation
206	// ---------------------------------------------------------------------------
207	
208	/** Viewport-relative scroll anchor: a message top plus a scrollTop fallback. */
209	interface MessageAnchor { messageId: string; offsetTop: number; scrollTop: number }
210	
211	interface VisitState {
212	  activeMessageId: string | null;
213	  expandedIds: Set<string>;
214	  detailsOpenId: string | null;
215	  anchor: MessageAnchor | null;
216	  /** Message ordering this state was built against (for removed-ID resolution). */
217	  order: string[];
218	}
219	
220	const visits = new Map<string, VisitState>();
221	/** Reactive holder for the currently displayed visit. */
222	const visitRef = ref<VisitState | null>(null);
223	let lastDataKey: string | null = null;
224	/**
225	 * Foreground activation intent, tracked separately from `lastDataKey`: a
226	 * loading transition that removed reader-owned focus owes the next ready
227	 * snapshot a message-focus restoration, even when the user reverses back to
228	 * the same key as the last loaded one (which would otherwise be classified as
229	 * an unfocused same-reference background replacement).
230	 */
231	let pendingFocusRestore = false;
232	
233	function visitKey(ref: ConversationRef): string {
234	  return `${ref.accountId}:${ref.conversationId}`;
235	}
236	
237	function keyOfDisplayed(): string | null {
238	  const conversation = props.conversation;
239	  const open = props.openRef;
240	  if (!conversation || !open) return null;
241	  if (conversation.ref.accountId !== open.accountId || conversation.ref.conversationId !== open.conversationId) return null;
242	  return visitKey(conversation.ref);
243	}
244	
245	/**
246	 * Prune removed message IDs and resolve removed active/anchor IDs by the
247	 * surviving old neighbors (next surviving old neighbor, then previous), so a
248	 * background replacement can never leave a stale message target.
249	 */
250	function pruneVisit(visit: VisitState, nextIds: string[]): void {
251	  const present = new Set(nextIds);
252	  const resolve = (id: string | null): string | null => {
253	    if (id === null || present.has(id)) return id;
254	    const oldIndex = visit.order.indexOf(id);
255	    if (oldIndex >= 0) {
256	      for (let i = oldIndex + 1; i < visit.order.length; i += 1) {
257	        const candidate = visit.order[i]!;
258	        if (present.has(candidate)) return candidate;
259	      }
260	      for (let i = oldIndex - 1; i >= 0; i -= 1) {
261	        const candidate = visit.order[i]!;
262	        if (present.has(candidate)) return candidate;
263	      }
264	    }
265	    return null;
266	  };
267	  visit.activeMessageId = resolve(visit.activeMessageId);
268	  visit.detailsOpenId = visit.detailsOpenId !== null && present.has(visit.detailsOpenId) ? visit.detailsOpenId : null;
269	  if (visit.anchor && !present.has(visit.anchor.messageId)) {
270	    const resolved = resolve(visit.anchor.messageId);
271	    visit.anchor = resolved
272	      ? { ...visit.anchor, messageId: resolved }
273	      : { messageId: '', offsetTop: 0, scrollTop: visit.anchor.scrollTop };
274	  }
275	  visit.expandedIds = new Set([...visit.expandedIds].filter((id) => present.has(id)));
276	  visit.order = [...nextIds];
277	}
278	
279	function captureScrollAnchor(visit: VisitState): MessageAnchor | null {
280	  const scroller = scrollerEl.value;
281	  if (!scroller || visit.order.length === 0) return null;
282	  const scrollerTop = scroller.getBoundingClientRect().top;
283	  for (const id of visit.order) {
284	    const el = messageEls.get(id);
285	    if (!el) continue;
286	    const top = el.getBoundingClientRect().top;
287	    if (top >= scrollerTop - 1 || id === visit.order[visit.order.length - 1]) {
288	      return { messageId: id, offsetTop: top - scrollerTop, scrollTop: scroller.scrollTop };
289	    }
290	  }
291	  return null;
292	}
293	
294	function restoreScroll(visit: VisitState, scroller: HTMLElement): void {
295	  const anchor = visit.anchor;
296	  if (!anchor) return;
297	  const el = messageEls.get(anchor.messageId);
298	  if (!el || scroller.clientHeight === 0 || !anchor.messageId) {
299	    // Fallback: the anchored message no longer exists; restore the raw offset.
300	    scroller.scrollTop = anchor.scrollTop;
301	    return;
302	  }
303	  const relative = el.getBoundingClientRect().top - scroller.getBoundingClientRect().top;
304	  scroller.scrollTop = scroller.scrollTop + (relative - anchor.offsetTop);
305	}
306	
307	function focusElement(el: HTMLElement | null | undefined, reveal: boolean): boolean {
308	  if (!el || !el.isConnected) return false;
309	  // Never move focus into an inert ancestor (e.g. a drawer covering the reader).
310	  if (el.closest('[inert]')) return false;
311	  el.focus({ preventScroll: true });
312	  if (reveal && typeof el.scrollIntoView === 'function') el.scrollIntoView({ block: 'nearest' });
313	  return document.activeElement === el;
314	}
315	
316	function focusMessageToggle(messageId: string, reveal: boolean): void {
317	  focusElement(messageEls.get(messageId)?.querySelector<HTMLElement>('.message-toggle'), reveal);
318	}
319	
320	type ComponentPublicInstance = import('vue').ComponentPublicInstance;
321	
322	function setMessageEl(el: Element | ComponentPublicInstance | null, messageId: string): void {
323	  if (el instanceof HTMLElement) messageEls.set(messageId, el);
324	  else messageEls.delete(messageId);
325	}
326	
327	let updateSeq = 0;
328	
329	/**
330	 * Loading teardown: if reader-owned focus was dropped to <body> because the
331	 * loading placeholder removed the focused message control, park it on the
332	 * persistent reader article. Never steals toolbar, rail, overlay, or other
333	 * unrelated focus — including a surface the user moved to while this delayed
334	 * work was in flight — respects inert ancestors, and is invalidated by any
335	 * newer update (a ready snapshot takes over via schedulePostUpdate).
336	 */
337	async function scheduleLoadingFocus(seq: number): Promise<void> {
338	  await nextTick();
339	  if (seq !== updateSeq) return;
340	  // Focus already lives on a surviving reader surface (e.g. the toolbar);
341	  // leave it exactly where it is.
342	  if (container.value?.contains(document.activeElement) ?? false) return;
343	  // Park only over focus that fell to <body> when the message control was
344	  // torn down: a still-focused rail/outside button keeps its focus.
345	  const active = document.activeElement;
346	  if (active !== null && active !== document.body) return;
347	  focusElement(container.value, false);
348	}
349	
350	/**
351	 * Post-update work for one conversation snapshot: restore the visit's scroll
352	 * position and, on a visit switch, focus the visit's active message toggle
353	 * (the article stays the empty/error fallback). The delayed focus is guarded
354	 * against a changed reference, a newer update, and inert ancestors.
355	 */
356	async function schedulePostUpdate(key: string, focusIntent: boolean, readerHadFocus: boolean, restoringAfterLoading: boolean, switched: boolean): Promise<void> {
357	  const seq = ++updateSeq;
358	  await nextTick();
359	  if (seq !== updateSeq || keyOfDisplayed() !== key) return;
360	  const visit = visits.get(key);
361	  const scroller = scrollerEl.value;
362	  if (visit && scroller) {
363	    // A returning visit restores its anchor; a first visit starts at the top
364	    // instead of inheriting the outgoing conversation's offset.
365	    if (visit.anchor) restoreScroll(visit, scroller);
366	    else if (switched) scroller.scrollTop = 0;
367	  }
368	  const messages = props.conversation?.messages ?? [];
369	  // A replacement that removed the focused message element must not drop
370	  // reader focus to <body>; resolve it to the visit's active message toggle.
371	  if (!focusIntent && readerHadFocus && !(container.value?.contains(document.activeElement) ?? false)) {
372	    if (messages.length === 0 || !visit?.activeMessageId) {
373	      focusElement(container.value, false);
374	      return;
375	    }
376	    // Scroll geometry was just restored; do not let focus-reveal shift it.
377	    focusMessageToggle(visit.activeMessageId, false);
378	    return;
379	  }
380	  if (!focusIntent) return;
381	  if (restoringAfterLoading) {
382	    // A delayed reversal must not yank focus from a surface the user moved to
383	    // while the loading placeholder was up: only our own parked article focus
384	    // (or focus that fell to <body>) may be promoted to a restoration target.
385	    // This ownership check must come BEFORE choosing the target so it also
386	    // protects the empty-visit article fallback, not just the message toggle.
387	    const active = document.activeElement;
388	    const inReader = active instanceof Node && (container.value?.contains(active) ?? false);
389	    if (inReader ? active !== container.value : active !== null && active !== document.body) return;
390	  }
391	  if (messages.length === 0 || !visit?.activeMessageId) {
392	    // Empty/error fallback: the reader article keeps focus instead of a
393	    // message control that does not exist.
394	    focusElement(container.value, false);
395	    return;
396	  }
397	  // A revisit with a saved anchor is positioned by restoreScroll; focusing
398	  // must not reveal-scroll and destroy the restored reading offset. A first
399	  // visit has no geometry yet, so reveal the focused header as needed.
400	  focusMessageToggle(visit.activeMessageId, visit.anchor === null);
401	}
402	
403	watch(
404	  () => props.conversation,
405	  (conversation) => {
406	    // Capture the outgoing visit's scroll geometry BEFORE any DOM teardown,
407	    // including the foreground null/loading transition: useMailbox clears the
408	    // conversation before the next detail arrives, and by the following
409	    // non-null update the outgoing message elements are already gone. This
410	    // watcher runs pre-flush, so the old elements are still live here. The
411	    // capture is a no-op once the elements are gone, so a loading/empty DOM
412	    // can never overwrite a saved anchor.
413	    const outgoing = lastDataKey !== null ? visits.get(lastDataKey) : null;
414	    if (outgoing && scrollerEl.value) {
415	      const captured = captureScrollAnchor(outgoing);
416	      if (captured) outgoing.anchor = captured;
417	    }
418	    const readerHadFocus = container.value?.contains(document.activeElement) ?? false;
419	    if (!conversation) {
420	      // Loading/error: visit state must not be erased. Only reader-owned
421	      // focus that is about to lose its message control is parked on the
422	      // persistent reader article (not <body>) and remembered for message
423	      // focus restoration on the next ready snapshot even when it resolves to
424	      // the last loaded key (immediate reversal). Focus that already lives
425	      // elsewhere (rail/overlay/outside) is never scheduled over.
426	      const seq = ++updateSeq;
427	      if (readerHadFocus) {
428	        pendingFocusRestore = true;
429	        void scheduleLoadingFocus(seq);
430	      }
431	      return;
432	    }
433	    const key = visitKey(conversation.ref);
434	    const previousKey = lastDataKey;
435	    const ids = conversation.messages.map((message) => message.id);
436	    let visit = visits.get(key);
437	    if (!visit) {
438	      const newest = ids[ids.length - 1] ?? null;
439	      // Reactive so state mutations (pruning resolution, command handlers)
440	      // publish through visitRef to templates and the active-ID watcher.
441	      visit = reactive<VisitState>({
442	        activeMessageId: newest,
443	        expandedIds: new Set(newest === null ? [] : [newest]),
444	        detailsOpenId: null,
445	        anchor: null,
446	        order: [...ids],
447	      });
448	      visits.set(key, visit);
449	    } else {
450	      pruneVisit(visit, ids);
451	    }
452	    visitRef.value = visit;
453	    lastDataKey = key;
454	    // Foreground activation is tracked separately from the last loaded key:
455	    // a reversal back to the same key still owes a focus restoration.
456	    const restoringAfterLoading = pendingFocusRestore;
457	    pendingFocusRestore = false;
458	    // A same-reference replacement never changes focus; a visit switch or a
459	    // reversed loading transition does.
460	    void schedulePostUpdate(key, key !== previousKey || restoringAfterLoading, readerHadFocus, restoringAfterLoading, key !== previousKey);
461	  },
462	  { immediate: true, flush: 'pre' },
463	);
464	
465	/** Loading/error fallback: keep the reader article focused, never steal toolbar focus. */
466	watch(
467	  () => props.state,
468	  async (state) => {
469	    if (state !== 'error') return;
470	    const seq = ++updateSeq;
471	    await nextTick();
472	    if (seq !== updateSeq) return;
473	    const active = document.activeElement;
474	    if (active instanceof Node && container.value?.contains(active)) return;
475	    focusElement(container.value, false);
476	  },
477	);
478	
479	// Reader focus identity + participant context (App consumes these).
480	watch(
481	  () => visitRef.value?.activeMessageId ?? null,
482	  (activeId) => { emit('activeMessage', activeId); },
483	  { immediate: true },
484	);
485	
486	const hoverParticipant = ref<{ messageId: string; address: Address } | null>(null);
487	const focusParticipant = ref<{ messageId: string; address: Address } | null>(null);
488	// Keyboard focus overrides hover independently; both restore the baseline on exit.
489	const effectiveParticipant = computed(() => focusParticipant.value ?? hoverParticipant.value);
490	
491	watch(
492	  effectiveParticipant,
493	  (value) => {
494	    const open = props.openRef;
495	    if (!value || !open) {
496	      emit('contactOverride', null);
497	      return;
498	    }
499	    emit('contactOverride', {
500	      ref: { ...open },
501	      messageId: value.messageId,
502	      displayName: value.address.displayName,
503	      mailbox: value.address.mailbox,
504	    });
505	  },
506	);
507	
508	function sameParticipant(
509	  current: { messageId: string; address: Address } | null,
510	  messageId: string,
511	  address: Address,
512	): boolean {
513	  return current !== null && current.messageId === messageId && current.address.mailbox === address.mailbox;
514	}
515	
516	function onParticipantEnter(message: Message, address: Address): void {
517	  hoverParticipant.value = { messageId: message.id, address };
518	}
519	
520	function onParticipantLeave(message: Message, address: Address): void {
521	  if (sameParticipant(hoverParticipant.value, message.id, address)) hoverParticipant.value = null;
522	}
523	
524	function onParticipantFocus(message: Message, address: Address): void {
525	  focusParticipant.value = { messageId: message.id, address };
526	}
527	
528	function onParticipantBlur(message: Message, address: Address): void {
529	  if (sameParticipant(focusParticipant.value, message.id, address)) focusParticipant.value = null;
530	}
