532	// ---------------------------------------------------------------------------
533	// Message rendering helpers + narrow message commands (exposed to App)
534	// ---------------------------------------------------------------------------
535	
536	/**
537	 * The visit a message command may act on: only a ready, matching displayed
538	 * reference qualifies. During loading the outgoing visit stays saved for
539	 * restoration, but stale commands must never mutate it.
540	 */
541	function displayedVisit(): VisitState | null {
542	  if (props.state !== 'ready') return null;
543	  const key = keyOfDisplayed();
544	  return key !== null ? visits.get(key) ?? null : null;
545	}
546	
547	function isActive(message: Message): boolean {
548	  return visitRef.value?.activeMessageId === message.id;
549	}
550	
551	/** Roving tabindex: the active toggle is the tab stop; the first is the fallback. */
552	function tabIndexFor(message: Message): 0 | -1 {
553	  if (isActive(message)) return 0;
554	  if ((visitRef.value?.activeMessageId ?? null) === null && message.id === (props.conversation?.messages[0]?.id ?? null)) return 0;
555	  return -1;
556	}
557	
558	function isExpanded(message: Message): boolean {
559	  return visitRef.value?.expandedIds.has(message.id) ?? false;
560	}
561	
562	function isDetailsOpen(message: Message): boolean {
563	  return visitRef.value?.detailsOpenId === message.id;
