/* A visually hidden leading Today caption takes no box at all. */
.row-group.visually-hidden {
  min-height: 0;
  padding: 0;
}

/* Reader: a bounded flex surface with its own content scroller; the toolbar
   (and its Back affordance) stays persistent while the message stack scrolls. */
.reader-pane,
.reader {
  min-height: 0;
  min-width: 0;
}

.reader-pane {
  display: flex;
  flex-direction: column;
  padding: 0.5rem 0.75rem;
}

.reader {
  flex: 1;
  display: flex;
  flex-direction: column;
}

.reader:focus {
  outline: none;
}

/* Quiet icon actions teleported into the app header: the hosts take no box of
   their own so the glyphs sit on the header's 32px pitch. Standalone (no
   host) they flow inline. */
.reader-back-host,
.reader-actions-host {
  display: contents;
}

.reader-actions {
  display: flex;
  align-items: center;
  flex: 0 0 auto;
}

/* Back arrow leads the context title; its glyph sits on the 50px inset. */
.header-tabs > .reader-back-host > .reader-back {
  align-self: center;
  margin-left: -8px;
  margin-right: -10px;
}

.header-tabs:has(> .reader-back-host > .reader-back) {
  align-items: center;
}

/* Honest-state text controls under the subject: one quiet line, only when present. */
.reader-meta-row {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 2px 12px;
  color: var(--text-secondary);
}

.reader-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}

/* Headline at the strong weight: the subject leads the reader without a third size. */
.reader-subject {
  font-size: var(--type-headline);
  font-weight: var(--weight-strong);
  line-height: var(--leading-headline);
  overflow-wrap: anywhere;
}

/* Loading identity: the list row's sender and date under the subject, then one
   quiet line. No motion; same type scale as the loaded reader. */
.reader-loading-identity {
  display: flex;
  gap: 12px;
  margin: 0.2rem 0;
  color: var(--text-secondary);
}

.reader-loading-quiet {
  color: var(--text-secondary);
}

.reader-context-note {
  max-width: 80ch;
  margin: 0.2rem 0;
  color: var(--text-secondary);
  font-size: var(--type-body);
}

/* Partial, unknown and unconfirmed star state read as Amber Notice. */
.reader-context-note[data-attention] {
  color: var(--warning);
}

.reader-pending {
  font-style: italic;
}

.messages {
  list-style: none;
  padding: 0;
  margin: 0;
}

.message {
  position: relative;
  border-top: 1px solid var(--rule);
  padding: 0.4rem 0.4rem 0.6rem;
  margin-bottom: 0.5rem;
}

/*
 * Current-message treatment: an accent-purple bar (color) plus a non-color
 * indication (a flat raised fill and a primary-color sender) so the focused
 * message never relies on color alone.
 */
.message.message-active {
  background: var(--surface-raised);
  box-shadow: inset 3px 0 0 var(--focus-accent);
}

/* The active bar is the focus indicator for the message toggle: no second ring.
   The fill, bold sender and bar remain; other controls keep the global ring. */
.message.message-active .message-toggle:focus-visible {
  outline: none;
}

.message.message-active .message-from {
  color: var(--text-primary);
  font-weight: var(--weight-strong);
}

.message-header {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

/* Quiet per-message reply glyph (latest, active message only). */
.message-reply {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 0;
  color: var(--icon-muted);
  background: transparent;
}

.message-reply:hover:not(:disabled),
.message-reply:focus-visible {
  color: var(--text-primary);
  background: transparent;
}

.message-reply-glyph {
  width: 1rem;
  height: 1rem;
}

/*
 * One line per message: sender, then (collapsed) a clipped body snippet or
 * (expanded) the recipients, then the compact date right-aligned. The full
 * date stays in the title, the screen-reader text and the Details disclosure.
 */
.message-toggle {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex: 1;
  min-width: 0;
  min-height: 2em;
  text-align: left;
  font-size: var(--type-body);
  color: var(--text-secondary);
  background: transparent;
  border: 0;
  padding: 0.1rem 0.2rem;
}

.message-from,
.message-to {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Collapsed senders share one 132px column so the snippets line up. */
.message-toggle[aria-expanded='false'] .message-from {
  flex: 0 0 11em;
}

.message-toggle[aria-expanded='false'] .message-to {
  display: none;
}

.message-snippet {
  flex: 1 1 0;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.message-time {
  flex: none;
  margin-left: auto;
  text-align: right;
  text-transform: uppercase;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

/*
 * Prose reads in the proportional face at the reading size. 65ch (width of "0")
 * is about 90 average proportional characters per line, short enough to follow.
 * Bodies that rely on column alignment (quotes, indented blocks, tables) keep
 * the raw monospace.
 */
.message-body {
  white-space: pre-wrap;
  font-family: var(--font-ui);
  font-size: var(--type-reading);
  line-height: var(--leading-reading);
  max-width: 65ch;
  color: var(--text-primary);
  overflow-wrap: anywhere;
  margin: 0.4rem 0;
}

.message-body.message-body-mono {
  font-family: var(--font-mono);
  font-size: var(--type-mono);
  line-height: var(--leading-mono);
  /* Hard-wrapped plain text is 72-78 columns; do not soft-wrap it a second time. */
  max-width: 88ch;
}

/* Per-message participant details disclosure (native details/summary). Only
   rendered visible inside an expanded message: the summary is a quiet line
   under the header (in flow, so it can never collide with the date or the reply
   glyph); the fields open below it. */
.message-details {
  font-size: var(--type-body);
}

.message-details summary {
  width: max-content;
  margin-left: 0.2rem;
  cursor: pointer;
  color: var(--icon-muted);
  list-style: none;
}

.message-details summary::-webkit-details-marker {
  display: none;
}

.message-details summary::before {
  content: '▸ ';
}

.message-details[open] summary::before {
  content: '▾ ';
}

.message-details summary:hover {
  color: var(--text-primary);
}

.message-details summary:focus-visible {
  outline: 2px solid var(--focus-accent);
  outline-offset: 1px;
}

.message-fields {
  display: grid;
  gap: 0.2rem;
  padding: 0.3rem 0;
}

.message-field {
  display: flex;
  gap: 0.4rem;
  min-width: 0;
}

.message-field-label {
  flex: 0 0 auto;
  color: var(--text-secondary);
}

.message-field-recipients {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

/* Participant context controls: hover/focus context, never navigation. */
.participant {
  overflow-wrap: anywhere;
  text-decoration: underline dotted;
  cursor: default;
  grid-template-columns: minmax(190px, 0.7fr) minmax(0, 2fr);
  gap: 0.8rem;
  min-height: 0;
}

.draft-list,
.composer {
  min-width: 0;
}

.draft-list-heading,
.composer-heading,
.composer-actions,
.conflict-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.draft-list-heading h2,
.composer-heading h2 {
  font-size: var(--type-body);
  font-weight: var(--weight-strong);
  margin: 0.25rem 0;
  overflow-wrap: anywhere;
}

/* Informational note: secondary text, not a warning. Warnings stay on
   status/error lines (draft-status, reply-source). */
.draft-local-note {
  margin: 0.3rem 0;
  font-size: var(--type-body);
  color: var(--text-secondary);
}

.reply-source,
.draft-status {
  margin: 0.3rem 0;
  font-size: var(--type-body);
  color: var(--warning);
}

/* Shared composer body (DraftEditorCore) inside any surface. */
.composer-body {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  min-width: 0;
}

/* "Draft" state flag: plain strong text, never uppercase/tracked and never a
   second accent — the reader's active-message bar already owns focus-accent. */
.draft-flag {
  color: var(--text-primary);
  font-weight: var(--weight-strong);
}

/* Composer footer, shared by the inline compose card, the docked reply
   composer and the drafts-drawer editor: actions right-aligned above a rule. */
.composer-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-top: 0.6rem;
  padding-top: 0.6rem;
  border-top: 1px solid var(--rule);
}

/* Inline confirm dialog (discard / reload) on any composer surface. */
.discard-confirm {
  border: 1px solid var(--rule);
  border-radius: 6px;
  padding: 0.4rem 0.6rem;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin-top: 0.4rem;
}

.draft-list ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.draft-row {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  width: 100%;
  padding: 0.4rem;
  border: 0;
  border-bottom: 1px solid var(--rule);
  border-radius: 0;
  background: transparent;
  color: inherit;
  text-align: left;
  overflow-wrap: anywhere;
}

.composer-fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.5rem;
}

.composer-fields label {
  display: flex;
  flex-direction: column;
  min-width: 0;
  gap: 0.2rem;
  font-size: var(--type-body);
}

.composer-fields input,
.composer-fields textarea {
  width: 100%;
  min-width: 0;
  font: inherit;
}

.composer-fields textarea {
  min-height: 8rem;
  resize: vertical;
  white-space: pre-wrap;
  grid-column: 1 / -1;
}

.composer-fields label:has(textarea) {
  grid-column: 1 / -1;
}

@media (max-width: 760px) {
  .drafts-pane {
    grid-template-columns: 1fr;
  }
}

/* Account gate, capability disclosures, and reader notices. */
.account-gate {
  padding: 12px 24px 12px 50px;
  color: var(--text-secondary);
.account-upgrade-disclosure,
.account-disconnect-warning {
  margin: 0;
  color: var(--text-secondary);
}

.account-actions {
  display: flex;
  gap: 0.5rem;
}

.reader-notice,
.reader-readonly,
.reader-recovery-snapshot {
  margin: 0.2rem 0;
  color: var(--warning);
  font-size: var(--type-body);
}

/* UX-03 discovery overlays: input owns keyboard focus; covered shell is inert. */
/* Coverage notes in Ash (was the undefined --text-muted with a #bbb fallback). */
.cached-coverage { margin: 0; padding: 6px 24px 6px 50px; color: var(--text-secondary); font-size: var(--type-body); }

/* UX-04 single-slot action notice: in-flow, never covers rows or reader controls. */
.action-notice {
  display: flex;
.action-copy { display: flex; flex: 1; flex-direction: column; gap: 2px; min-width: 0; overflow-wrap: anywhere; }
.action-disabled-reason { color: var(--text-secondary); }
.command-overlay kbd { flex-shrink: 0; min-width: 20px; padding: 1px 6px; border-radius: 4px; background: var(--surface-contact); color: var(--text-secondary); font: inherit; text-align: center; font-variant-numeric: tabular-nums; }
.action-hint, .command-overlay > [role='status'] { margin: 0; padding: 8px 16px; color: var(--text-secondary); }
.action-hint { border-top: 1px solid var(--divider); }

/* Modal attachment chooser: the shared panel, wider for file names and URLs. */
.action-overlay.attachment-chooser { width: min(46rem, 100%); padding: 12px 16px 16px; }

/* UX-06: compact overlapping Inbox views, no folder or classifier metaphor. */
.split-editor { max-height: 38vh; overflow: auto; padding: .5rem 0; font-size: var(--type-body); }
.split-editor p { max-width: 75ch; margin: .35rem 0 .6rem; }
.split-editor fieldset { border: 0; padding: 0; margin: 0 0 .6rem; display: flex; flex-wrap: wrap; gap: .6rem 1rem; align-items: center; }
.split-editor label { display: flex; align-items: center; gap: .4rem; max-width: 100%; }
.split-editor input:not([type="checkbox"]) { min-width: 0; width: 15rem; max-width: 100%; padding: .3rem; font: inherit; }
.split-editor select { padding: .3rem; }

/* UX-05 selection action bar: compact, in normal flow above the list. */
.selection-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 12px;
  min-height: 36px;
  padding: 6px 0;
  font-size: var(--type-body);
}
.selection-scope { margin: 0; }
.selection-loaded-scope { color: var(--text-secondary); }
.selection-actions { display: flex; flex-wrap: wrap; gap: 2px; margin-left: -8px; }
.selection-limit { margin: 0; flex-basis: 100%; color: var(--warning); }
.reader-selection-scope {
  margin: 0 0 6px;
  color: var(--text-secondary);
  font-size: var(--type-body);
}

/* UX-05 Activity group sections. */
.activity-groups { margin-bottom: 1rem; }
.activity-groups-title { margin: .2rem 0 .4rem; font-size: var(--type-body); font-weight: var(--weight-strong); }
.activity-group-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: .35rem; }
.activity-group-toggle { width: 100%; text-align: left; cursor: pointer; }
.activity-group-detail { margin-top: .4rem; padding: .5rem; border: 1px solid var(--rule); border-radius: 4px; }
.activity-group-request { margin: 0 0 .4rem; color: var(--text-secondary); font-size: var(--type-body); overflow-wrap: anywhere; }
.activity-group-members { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: .35rem; }
.activity-group-member { display: flex; flex-wrap: wrap; align-items: baseline; gap: .4rem; }

/*
 * Inline compose card (new-message editor): an in-flow block in the central
 * column — the area where the inbox list normally is — or docked at the bottom
 * of the reader pane. Never a fixed overlay: no backdrop, no dimming, so the
 * rail, header and contact pane stay visible and interactive while composing.
 * DESIGN.md tokens: 1px Seam (divider) border, 10px radius, Lifted Charcoal
 * (surface-raised) fill.
 */
.compose-card {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  margin: 6px 24px 12px 50px;
  background: var(--surface-raised);
  color: var(--text-primary);
  border: 1px solid var(--divider);
  border-radius: 10px;
  padding: 12px 16px 16px;
  font-size: var(--type-body);
  line-height: var(--leading-ui);
}
/* Docked at the bottom of the reader pane (editor active while a reader is
   open): same raised-surface card, compact. Full 1px border — no accent side
   stripe, so the reader's active-message bar keeps the single accent signal. */
.reader-pane > .compose-card {
  flex: 0 0 auto;
  max-height: 45%;
  margin: 0.5rem 0 0;
  border: 1px solid var(--divider);
  border-radius: 6px;
}

/* Docked composers get a shorter body so the thread stays visible above. */
.reader-pane .composer-fields textarea {
  min-height: 5rem;
}
  padding: 4px 8px;
  font: inherit;
  cursor: pointer;
}

:where(button:not(:disabled):hover) {
  background: var(--surface-raised);
}

/* On the raised composer surfaces the ghost hover fill equals the card
   background, so it would be invisible; use the stronger fill there. */
:where(.compose-card, .reply-composer) :where(button:not(:disabled):hover) {
  background: var(--focus-fill);
}

:where(button:not(:disabled):active) {
  background: var(--focus-fill);
}

:where(button:disabled) {
  opacity: 0.45;
  cursor: default;
}

/*
 * Utility chip: a Lifted Charcoal fill with a 1px Seam border, only inside
 * utility drawers, the modal attachment chooser, recovery banners and the
 * synthetic workspace strip. Same 24px height as the ghost button.
 */
:where(.utility-drawer, .attachment-chooser, .recovery-banner, .header-alert, .workspace-header) :where(button) {
  background: var(--surface-raised);
  border: 1px solid var(--divider);
  padding: 3px 8px;
}

:where(.utility-drawer, .attachment-chooser, .recovery-banner, .header-alert, .workspace-header) :where(button:not(:disabled):hover) {
  background: var(--focus-fill);
}

button:focus-visible {
