.field-row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-width: 0;
  min-height: 28px;
  font-size: var(--type-body);
}

.field-label {
  flex: 0 0 3.5rem;
  color: var(--text-secondary);
}

.field-row .field-input,
.field-row .field-summary {
  flex: 1 1 auto;
  min-width: 0;
  padding: 3px 6px;
  font: inherit;
}

.field-row .field-input {
  background: transparent;
  border: 1px solid transparent;
  border-radius: 4px;
}

.field-row .field-input:hover:not(:disabled) {
  border-color: var(--rule);
}

.field-row .field-input:focus-visible {
  border-color: var(--focus-accent);
  outline: 1px solid var(--focus-accent);
  outline-offset: -2px;
}

/* The collapsed reply recipient: a real button that opens the To input. */
.field-row .field-summary {
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-primary);
}

.field-row .field-summary:hover:not(:disabled) {
  background: var(--focus-fill);
}

.field-toggle {
  flex: none;
  color: var(--text-secondary);
}

.field-toggle:hover:not(:disabled) {
  color: var(--text-primary);
}

.field-body {
  display: flex;
  flex-direction: column;
  min-width: 0;
  margin-top: 0.25rem;
}

.field-textarea {
  width: 100%;
  min-width: 0;
  /* At least six lines at the 12px body size; grows with its text up to the pane. */
  min-height: 7.5rem;
  max-height: 50vh;
  padding: 6px 8px;
  resize: vertical;
  white-space: pre-wrap;
  font: inherit;
  line-height: var(--leading-ui);
}

@media (max-width: 760px) {
  .drafts-pane {
    grid-template-columns: 1fr;
  }
}

/* Account gate, capability disclosures, and reader notices. */
.account-gate {
  padding: 12px 24px 12px 50px;
  color: var(--text-secondary);
}

.account-panel {

input.command:
python3 -I - <<'E'
p='src/assets/style.css'
s=open(p).read()
old='''.field-row .field-input {
  background: transparent;
  border: 1px solid transparent;
  border-radius: 4px;
}

.field-row .field-input:hover:not(:disabled) {
  border-color: var(--rule);
}
'''
new='''/* A quiet Seam underline at rest so an empty row still shows where to type;
   the full Seam border returns on hover (DESIGN.md "Inputs / Fields"). */
.field-row .field-input {
  background: transparent;
  border: 1px solid transparent;
  border-bottom-color: var(--divider);
  border-radius: 4px;
}

.field-row .field-input:hover:not(:disabled) {
  border-color: var(--divider);
}
'''
assert old in s
open(p,'w').write(s.replace(old,new))
